/// 📤️ Prints every 2-space-indented `Op::print_op` line for one `apply`/`amend` body,
/// erroring exactly like `print_edit_lines` if any op prints a line containing a newline.
async fn print_indented_ops<Op: OpText>(out: &mut String, mutations: &[Op]) -> Result<(), VcsError> {
    for mutation in mutations {
        let printed = mutation.print_op();
        if printed.contains('\n') {
            return Err(VcsError::Serialize("op-text print_op must not contain a newline".into()));
        }
        out.push_str("  ");
        out.push_str(&printed);
        out.push('\n');
    }
    Ok(())
}

/// 📥️ Parses every already-2-space-indented body line of an `apply`/`amend` command as one
/// operation each — the command-level twin of `replay_ops`'s indented-op-line branch.
/// All-or-nothing: on any failure every operation parsed so far retires through its technology's cold disposal.
async fn parse_indented_ops<P, Op: OpText + self::Mutation<P>>(body_lines: &[&str]) -> Result<Vec<Op>, TextError> {
    let mut mutations = Vec::with_capacity(body_lines.len());
    for raw in body_lines {
        let parsed = match raw.starts_with("  ") {
            true => Op::parse_op(raw.trim()),
            false => Err(semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue,(format!("expected a 2-space-indented op line, got: {raw:?}")).to_string(),semio_framework_diagnostic::TextSpan::at(1,1))),
        };
        match parsed {
            Ok(operation) => mutations.push(operation),
            Err(error) => {
                retire_operations::<P, Op>(mutations);
                return Err(error);
            }
        }
    }
    Ok(mutations)
}

/// 📥️ Strips exactly one 2-space indent level from every line, joining them back into a
/// standalone command text — used to recurse `parse_command` into a `semantic-undo`/
/// `compensating-action` nested command block.
async fn dedent_command_lines(lines: &[&str]) -> Result<String, TextError> {
    let mut out = String::new();
    for raw in lines {
        if !raw.starts_with("  ") {
            return Err(semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue,(format!("expected a 2-space-indented nested command line, got: {raw:?}")).to_string(),semio_framework_diagnostic::TextSpan::at(1,1)));
        }
        out.push_str(&raw[2..]);
        out.push('\n');
    }
    Ok(out)
}

/// 📤️ Prints a `ArtifactCommand` as its one-line-per-structural-field header, plus any
/// 2-space-indented operation lines (`Apply`) or a further-indented nested command
/// block (`UndoWithPolicy`'s `semantic_command`) — the maximum-token-efficient textual twin of
/// `encode_command`. `Author::avatar` is never printed, mirroring `OpsAuthor`'s `by=[...]` law.
pub async fn print_command<Op: OpText>(command: &ArtifactCommand<Op>) -> Result<String, VcsError> {
    let mut out = String::new();
    match command {
        ArtifactCommand::Apply { mutations, description, transaction } => {
            let (transaction, tool) = transaction_text(transaction.as_ref());
            out.push_str(&CommandHeaderLine::Apply { description: description.clone(), transaction, tool }.print_op());
            out.push('\n');
            print_indented_ops(&mut out, mutations).await?;
        }
        ArtifactCommand::Undo => {
            out.push_str(&CommandHeaderLine::Undo { policy: None }.print_op());
            out.push('\n');
        }
        ArtifactCommand::Redo => {
            out.push_str(&CommandHeaderLine::Redo.print_op());
            out.push('\n');
        }
        ArtifactCommand::UndoWithPolicy { policy, semantic_command } => {
            out.push_str(&CommandHeaderLine::Undo { policy: Some(undo_policy_to_token(*policy).await.to_string()) }.print_op());
            out.push('\n');
            if let Some(nested) = semantic_command {
                let nested_text = Box::pin(print_command(nested)).await?;
                for line in nested_text.lines() {
                    out.push_str("  ");
                    out.push_str(line);
                    out.push('\n');
                }
            }
        }
        ArtifactCommand::CommitCheckpoint { message, authors } => {
            let header = CommandHeaderLine::CommitCheckpoint { message: message.clone(), by: authors.iter().map(OpsAuthor::from).collect() };
            out.push_str(&header.print_op());
            out.push('\n');
        }
        ArtifactCommand::CreateAlternative { name } => {
            out.push_str(&CommandHeaderLine::CreateAlternative { name: name.clone() }.print_op());
            out.push('\n');
        }
        ArtifactCommand::SwitchAlternative { alternative_id } => {
            out.push_str(&CommandHeaderLine::SwitchAlternative { id: alternative_id.clone() }.print_op());
            out.push('\n');
        }
        ArtifactCommand::CheckoutCheckpoint { checkpoint_id } => {
            out.push_str(&CommandHeaderLine::Checkout { id: checkpoint_id.clone() }.print_op());
            out.push('\n');
        }
        ArtifactCommand::ApplyInLane { mutations, description, lane, transaction } => {
            let (transaction, tool) = transaction_text(transaction.as_ref());
            out.push_str(&CommandHeaderLine::ApplyInLane { description: description.clone(), lane: history_lane_to_token(*lane).await.to_string(), transaction, tool }.print_op());
            out.push('\n');
            print_indented_ops(&mut out, mutations).await?;
        }
        ArtifactCommand::UndoInLane { lane } => {
            out.push_str(&CommandHeaderLine::UndoInLane { lane: history_lane_to_token(*lane).await.to_string() }.print_op());
            out.push('\n');
        }
        ArtifactCommand::RedoInLane { lane } => {
            out.push_str(&CommandHeaderLine::RedoInLane { lane: history_lane_to_token(*lane).await.to_string() }.print_op());
            out.push('\n');
        }
        ArtifactCommand::IngestRemote { .. } => {
            return Err(VcsError::Serialize("IngestRemote has no text command form".into()));
        }
        ArtifactCommand::PruneDrafts => {
            out.push_str(&CommandHeaderLine::PruneDrafts.print_op());
            out.push('\n');
        }
        ArtifactCommand::SetMergePolicy { policy } => {
            out.push_str(&CommandHeaderLine::SetMergePolicy { policy: merge_policy_to_token(*policy).await.to_string() }.print_op());
            out.push('\n');
        }
        ArtifactCommand::ResolveConflict { conflict_id, resolution } => {
            out.push_str(&CommandHeaderLine::ResolveConflict { conflict_id: conflict_id.clone(), resolution: conflict_resolution_to_token(*resolution).await.to_string() }.print_op());
            out.push('\n');
        }
        ArtifactCommand::Supersede { scope, inputs } => {
            out.push_str(&CommandHeaderLine::Supersede { scope: scope.clone() }.print_op());
            out.push('\n');
            print_supersede_inputs(&mut out, inputs)?;
        }
        ArtifactCommand::CreateAlternativeWithSupersede { name, inputs } => {
            out.push_str(&CommandHeaderLine::CreateAlternativeWithSupersede { name: name.clone() }.print_op());
            out.push('\n');
            print_supersede_inputs(&mut out, inputs)?;
        }
        ArtifactCommand::AppendTransaction { mutations, transaction } => {
            out.push_str(&CommandHeaderLine::AppendTransaction { transaction: transaction.id.clone(), tool: transaction.tool.clone() }.print_op());
            out.push('\n');
            print_indented_ops(&mut out, mutations).await?;
        }
        ArtifactCommand::CommitTransaction { transaction_id } => {
            out.push_str(&CommandHeaderLine::CommitTransaction { id: transaction_id.clone() }.print_op());
            out.push('\n');
        }
        ArtifactCommand::AbortTransaction { transaction_id } => {
            out.push_str(&CommandHeaderLine::AbortTransaction { id: transaction_id.clone() }.print_op());
            out.push('\n');
        }
    }
    Ok(out)
}

/// 📥️ Parses a `print_command`-produced (or hand-authored) command text back into a
/// `ArtifactCommand`. LAW: `parse_command(&print_command(c)?) == Ok(c)` for every `c`.
pub async fn parse_command<P, Op: OpText + self::Mutation<P>>(text: &str) -> Result<ArtifactCommand<Op>, TextError> {
    let all_lines: Vec<&str> = text.lines().collect();
    let mut header: Option<(u32, &str)> = None;
    let mut body_start = all_lines.len();
    for (index, raw) in all_lines.iter().enumerate() {
        let trimmed = raw.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        header = Some((index as u32 + 1, trimmed));
        body_start = index + 1;
        break;
    }
    let (header_line_no, header_text) = header.ok_or_else(|| semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue,("empty command text").to_string(),semio_framework_diagnostic::TextSpan::at(1,1)))?;
    let header_line = CommandHeaderLine::parse_op(header_text).map_err(|error| TextError { span: TextSpan::at(header_line_no, error.span.column), ..error })?;
    let body_lines: Vec<&str> = all_lines[body_start..].iter().filter(|line| !line.trim().is_empty() && !line.trim().starts_with('#')).copied().collect();

    match header_line {
        CommandHeaderLine::Apply { description, transaction, tool } => {
            let transaction = transaction_from_text(transaction, tool)?;
            let mutations = parse_indented_ops::<P, Op>(&body_lines).await?;
            if mutations.is_empty() {
                return Err(semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue,("apply requires at least one operation line").to_string(),semio_framework_diagnostic::TextSpan::at(1,1)));
            }
            Ok(ArtifactCommand::Apply { mutations, description, transaction })
        }
        CommandHeaderLine::Undo { policy: None } => Ok(ArtifactCommand::Undo),
        CommandHeaderLine::Undo { policy: Some(token) } => {
            let policy = parse_undo_policy_token(&token).await?;
            let semantic_command = if body_lines.is_empty() {
                None
            } else {
                let dedented = dedent_command_lines(&body_lines).await?;
                Some(Box::new(Box::pin(parse_command::<P, Op>(&dedented)).await?))
            };
            Ok(ArtifactCommand::UndoWithPolicy { policy, semantic_command })
        }
        CommandHeaderLine::Redo => Ok(ArtifactCommand::Redo),
        CommandHeaderLine::CommitCheckpoint { message, by } => Ok(ArtifactCommand::CommitCheckpoint { message, authors: by.into_iter().map(Author::from).collect() }),
        CommandHeaderLine::CreateAlternative { name } => Ok(ArtifactCommand::CreateAlternative { name }),
        CommandHeaderLine::SwitchAlternative { id } => Ok(ArtifactCommand::SwitchAlternative { alternative_id: id }),
        CommandHeaderLine::Checkout { id } => Ok(ArtifactCommand::CheckoutCheckpoint { checkpoint_id: id }),
        CommandHeaderLine::PruneDrafts => Ok(ArtifactCommand::PruneDrafts),
        CommandHeaderLine::ApplyInLane { description, lane, transaction, tool } => {
            let transaction = transaction_from_text(transaction, tool)?;
            let lane = parse_history_lane_token(&lane).await?;
            let mutations = parse_indented_ops::<P, Op>(&body_lines).await?;
            if mutations.is_empty() {
                return Err(semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue,("apply-in-lane requires at least one operation line").to_string(),semio_framework_diagnostic::TextSpan::at(1,1)));
            }
            Ok(ArtifactCommand::ApplyInLane { mutations, description, lane, transaction })
        }
        CommandHeaderLine::UndoInLane { lane } => Ok(ArtifactCommand::UndoInLane { lane: parse_history_lane_token(&lane).await? }),
        CommandHeaderLine::RedoInLane { lane } => Ok(ArtifactCommand::RedoInLane { lane: parse_history_lane_token(&lane).await? }),
        CommandHeaderLine::SetMergePolicy { policy } => Ok(ArtifactCommand::SetMergePolicy { policy: parse_merge_policy_token(&policy).await? }),
        CommandHeaderLine::ResolveConflict { conflict_id, resolution } => Ok(ArtifactCommand::ResolveConflict { conflict_id, resolution: parse_conflict_resolution_token(&resolution).await? }),
        CommandHeaderLine::Supersede { scope } => Ok(ArtifactCommand::Supersede { scope, inputs: parse_supersede_inputs::<P, Op>(&body_lines)? }),
        CommandHeaderLine::CreateAlternativeWithSupersede { name } => Ok(ArtifactCommand::CreateAlternativeWithSupersede { name, inputs: parse_supersede_inputs::<P, Op>(&body_lines)? }),
        CommandHeaderLine::AppendTransaction { transaction, tool } => {
            let mutations = parse_indented_ops::<P, Op>(&body_lines).await?;
            if mutations.is_empty() {
                return Err(semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue,("append-transaction requires at least one operation line").to_string(),semio_framework_diagnostic::TextSpan::at(1,1)));
            }
            Ok(ArtifactCommand::AppendTransaction { mutations, transaction: protocol::TransactionRef { id: transaction, tool } })
        }
        CommandHeaderLine::CommitTransaction { id } => Ok(ArtifactCommand::CommitTransaction { transaction_id: id }),
        CommandHeaderLine::AbortTransaction { id } => Ok(ArtifactCommand::AbortTransaction { transaction_id: id }),
    }
}

/// 🧾️ A transaction reference as its two text attributes.
fn transaction_text(transaction: Option<&protocol::TransactionRef>) -> (Option<String>, Option<String>) {
    match transaction {
        Some(transaction) => (Some(transaction.id.clone()), Some(transaction.tool.clone())),
        None => (None, None),
    }
}

/// 🧾️ Inverse of [`transaction_text`]: both attributes or neither.
fn transaction_from_text(transaction: Option<String>, tool: Option<String>) -> Result<Option<protocol::TransactionRef>, TextError> {
    match (transaction, tool) {
        (Some(id), Some(tool)) => Ok(Some(protocol::TransactionRef { id, tool })),
        (None, None) => Ok(None),
        _ => Err(semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue,("a transaction needs both its id and its tool").to_string(),semio_framework_diagnostic::TextSpan::at(1,1))),
    }
}

/// 🧾️ Binary twin of [`transaction_text`]: the id and tool strings after a `0b10` presence bit.
fn write_command_transaction(out: &mut Vec<u8>, transaction: Option<&protocol::TransactionRef>) {
    if let Some(transaction) = transaction {
        write_command_str(out, &transaction.id);
        write_command_str(out, &transaction.tool);
    }
}

fn read_command_transaction(reader: &mut crate::os_pack::ByteReader<'_>, presence: u8) -> Result<Option<protocol::TransactionRef>, crate::os_spr::ProtocolError> {
    if presence & 0b10 == 0 {
        return Ok(None);
    }
    let id = read_command_str(reader)?;
    let tool = read_command_str(reader)?;
    Ok(Some(protocol::TransactionRef { id, tool }))
}

/// 🎯️ Format byte every encoded command starts with — matches `crate::os_dsl::op_rt::OP_BINARY_FORMAT`
/// (B-R6 "one wire convention": `format u8 | ordinal varint | record body`).
pub const COMMAND_BINARY_FORMAT: u8 = 1;

fn write_command_str(out: &mut Vec<u8>, s: &str) {
    crate::os_pack::write_varint_u64(out, s.len() as u64);
    out.extend_from_slice(s.as_bytes());
}

fn read_command_str(reader: &mut crate::os_pack::ByteReader<'_>) -> Result<String, crate::os_spr::ProtocolError> {
    let len = reader.read_varint_u64()?;
    let bytes = reader.read_bytes(len as usize)?;
    std::str::from_utf8(bytes).map(str::to_string).map_err(|error| crate::os_spr::ProtocolError::Malformed { what: "command string", offset: 0, detail: error.to_string() })
}

fn write_command_ops<Op: OpBinary>(out: &mut Vec<u8>, mutations: &[Op]) -> Result<(), crate::os_spr::ProtocolError> {
    crate::os_pack::write_varint_u64(out, mutations.len() as u64);
    for mutation in mutations {
        let bytes = mutation.encode_op()?;
        crate::os_pack::write_varint_u64(out, bytes.len() as u64);
        out.extend_from_slice(&bytes);
    }
    Ok(())
}

/// 🪣️ Reads a command's operation list all-or-nothing: on any failure every operation decoded so far retires through its
/// technology's cold disposal, so a refused list never drops a live operation.
fn read_command_ops<P, Op: OpBinary + self::Mutation<P>>(reader: &mut crate::os_pack::ByteReader<'_>) -> Result<Vec<Op>, CommandDecodeError> {
    let count = reader.read_varint_u64()?;
    let mut mutations = Vec::with_capacity(count.min(reader.remaining() as u64) as usize);
    for index in 0..count as usize {
        match read_command_op(reader) {
            Ok(operation) => mutations.push(operation),
            Err(error) => {
                retire_operations::<P, Op>(mutations);
                return Err(CommandDecodeError::Operation { index, error });
            }
        }
    }
    Ok(mutations)
}

/// 🔹️ One length-prefixed operation of a command.
fn read_command_op<Op: OpBinary>(reader: &mut crate::os_pack::ByteReader<'_>) -> Result<Op, crate::os_spr::ProtocolError> {
    let len = reader.read_varint_u64()?;
    Op::decode_op(reader.read_bytes(len as usize)?)
}

/// 🧯️ Why a binary [`ArtifactCommand`] did not decode ([`ArtifactCommand::decode_command`]). Decoding is all-or-nothing:
/// every operation decoded before the failure retired through its technology's cold disposal.
#[derive(Clone, Debug, PartialEq)]
pub enum CommandDecodeError {
    /// 📐️ The command's own layout — its format, ordinal, a field, the framing of a list, or bytes past its end.
    Layout(crate::os_spr::ProtocolError),
    /// 🧩️ Entry `index` of the command's operation list or supersede inputs does not decode as one operation.
    Operation { index: usize, error: crate::os_spr::ProtocolError },
}

impl std::fmt::Display for CommandDecodeError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Layout(error) => write!(formatter, "command layout: {error}"),
            Self::Operation { index, error } => write!(formatter, "command operation {index}: {error}"),
        }
    }
}

impl std::error::Error for CommandDecodeError {}

impl From<crate::os_spr::ProtocolError> for CommandDecodeError {
    fn from(error: crate::os_spr::ProtocolError) -> Self {
        Self::Layout(error)
    }
}

impl From<crate::os_pack::PackError> for CommandDecodeError {
    fn from(error: crate::os_pack::PackError) -> Self {
        Self::Layout(error.into())
    }
}

semio_framework_diagnostic::fault_from_error!(CommandDecodeError, semio_framework_diagnostic::FaultOrigin::Module, "module.store.command");

/// 🧊️ Retires operations nobody will apply through their technology's cold disposal.
fn retire_operations<P, Op: self::Mutation<P>>(operations: impl IntoIterator<Item = Op>) {
    for operation in operations {
        Op::retire_cold(operation);
    }
}

/// 🪦️ Retires every operation a command owns — its operation list, its supersede replacements, its nested command.
fn retire_command<P, Op: self::Mutation<P>>(command: ArtifactCommand<Op>) {
    match command {
        ArtifactCommand::Apply { mutations, .. } | ArtifactCommand::ApplyInLane { mutations, .. } | ArtifactCommand::AppendTransaction { mutations, .. } => retire_operations::<P, Op>(mutations),
        ArtifactCommand::Supersede { inputs, .. } | ArtifactCommand::CreateAlternativeWithSupersede { inputs, .. } => retire_supersede_inputs::<P, Op>(inputs),
        ArtifactCommand::UndoWithPolicy { semantic_command: Some(nested), .. } => retire_command::<P, Op>(*nested),
        ArtifactCommand::UndoWithPolicy { semantic_command: None, .. }
        | ArtifactCommand::Undo
        | ArtifactCommand::Redo
        | ArtifactCommand::UndoInLane { .. }
        | ArtifactCommand::RedoInLane { .. }
        | ArtifactCommand::CommitCheckpoint { .. }
        | ArtifactCommand::CreateAlternative { .. }
        | ArtifactCommand::SwitchAlternative { .. }
        | ArtifactCommand::CheckoutCheckpoint { .. }
        | ArtifactCommand::IngestRemote { .. }
        | ArtifactCommand::PruneDrafts
        | ArtifactCommand::SetMergePolicy { .. }
        | ArtifactCommand::ResolveConflict { .. }
        | ArtifactCommand::CommitTransaction { .. }
        | ArtifactCommand::AbortTransaction { .. } => {}
    }
}

/// 🎯️ B-R6 "one documented generic impl": `ArtifactCommand<Op>` cannot go through
/// `#[derive(crate::os_dsl::DslOps)]` like every concrete per-technology `Mutation` enum does — it is generic
/// over a FOREIGN `Op: OpBinary` from whichever technology is dispatching, and the derive
/// only lowers a CONCRETE type's own fields to a `RecordSpec`; there is no way to describe "some
/// other crate's already-`OpBinary` type" as a `crate::os_dsl::DslField` shape. This hand-written impl is the
/// one place `ArtifactCommand`'s binary layout is still spelled out by hand — everywhere else in the
/// workspace, encoding is derive-generated. Byte layout matches the convention exactly: `format u8
/// (=1, see `COMMAND_BINARY_FORMAT`) | fixed variant ordinal varint (one stable number per variant; LEB128 varints
/// under 128 are single bytes) | body`. The binary twin of `print_command`/`parse_command`. LAW:
/// `ArtifactCommand::decode_command(&command.encode_command()?) == Ok(command)`. Not an `OpBinary`: decoding needs the
/// operations' projection `P` to retire what a refused command decoded, which the P-agnostic `OpBinary` cannot name.
impl<Op: OpBinary> ArtifactCommand<Op> {
    /// 🛫️ The command's binary form.
    pub fn encode_command(&self) -> Result<Vec<u8>, crate::os_spr::ProtocolError> {
        let mut out = vec![COMMAND_BINARY_FORMAT];
        match self {
            ArtifactCommand::Apply { mutations, description, transaction } => {
                crate::os_pack::write_varint_u64(&mut out, 0);
                out.push(u8::from(description.is_some()) | (u8::from(transaction.is_some()) << 1));
                if let Some(text) = description {
                    write_command_str(&mut out, text);
                }
                write_command_transaction(&mut out, transaction.as_ref());
                write_command_ops(&mut out, mutations)?;
            }
            ArtifactCommand::Undo => crate::os_pack::write_varint_u64(&mut out, 1),
            ArtifactCommand::Redo => crate::os_pack::write_varint_u64(&mut out, 2),
            ArtifactCommand::UndoWithPolicy { policy, semantic_command } => {
                crate::os_pack::write_varint_u64(&mut out, 3);
                out.push(undo_policy_ordinal(*policy));
                out.push(if semantic_command.is_some() { 0b01 } else { 0 });
                if let Some(nested) = semantic_command {
                    let nested_bytes = nested.encode_command()?;
                    crate::os_pack::write_varint_u64(&mut out, nested_bytes.len() as u64);
                    out.extend_from_slice(&nested_bytes);
                }
            }
            ArtifactCommand::CommitCheckpoint { message, authors } => {
                crate::os_pack::write_varint_u64(&mut out, 4);
                out.push(if message.is_some() { 0b01 } else { 0 });
                if let Some(text) = message {
                    write_command_str(&mut out, text);
                }
                crate::os_pack::write_varint_u64(&mut out, authors.len() as u64);
                for author in authors {
                    write_command_str(&mut out, &author.id);
                    write_command_str(&mut out, &author.name);
                }
            }
            ArtifactCommand::CreateAlternative { name } => {
                crate::os_pack::write_varint_u64(&mut out, 5);
                write_command_str(&mut out, name);
            }
            ArtifactCommand::SwitchAlternative { alternative_id } => {
                crate::os_pack::write_varint_u64(&mut out, 6);
                write_command_str(&mut out, alternative_id);
            }
            ArtifactCommand::CheckoutCheckpoint { checkpoint_id } => {
                crate::os_pack::write_varint_u64(&mut out, 7);
                write_command_str(&mut out, checkpoint_id);
            }
            ArtifactCommand::IngestRemote { envelope } => {
                crate::os_pack::write_varint_u64(&mut out, 9);
                let mut bytes = Vec::new();
                crate::os_spr::encode_envelope(envelope, &mut bytes);
                crate::os_pack::write_varint_u64(&mut out, bytes.len() as u64);
                out.extend_from_slice(&bytes);
            }
            ArtifactCommand::PruneDrafts => crate::os_pack::write_varint_u64(&mut out, 10),
            ArtifactCommand::ApplyInLane { mutations, description, lane, transaction } => {
                crate::os_pack::write_varint_u64(&mut out, 11);
                out.push(u8::from(description.is_some()) | (u8::from(transaction.is_some()) << 1));
                if let Some(text) = description {
                    write_command_str(&mut out, text);
                }
                write_command_transaction(&mut out, transaction.as_ref());
                out.push(history_lane_ordinal(*lane));
                write_command_ops(&mut out, mutations)?;
            }
            ArtifactCommand::UndoInLane { lane } => {
                crate::os_pack::write_varint_u64(&mut out, 13);
                out.push(history_lane_ordinal(*lane));
            }
            ArtifactCommand::RedoInLane { lane } => {
                crate::os_pack::write_varint_u64(&mut out, 14);
                out.push(history_lane_ordinal(*lane));
            }
            ArtifactCommand::SetMergePolicy { policy } => {
                crate::os_pack::write_varint_u64(&mut out, 15);
                out.push(policy.as_u8());
            }
            ArtifactCommand::ResolveConflict { conflict_id, resolution } => {
                crate::os_pack::write_varint_u64(&mut out, 16);
                write_command_str(&mut out, conflict_id);
                out.push(conflict_resolution_ordinal(*resolution));
            }
            ArtifactCommand::Supersede { scope, inputs } => {
                crate::os_pack::write_varint_u64(&mut out, 17);
                out.push(if scope.is_some() { 0b01 } else { 0 });
                if let Some(scope) = scope {
                    write_command_str(&mut out, scope);
                }
                write_supersede_inputs(&mut out, inputs)?;
            }
            ArtifactCommand::CreateAlternativeWithSupersede { name, inputs } => {
                crate::os_pack::write_varint_u64(&mut out, 18);
                write_command_str(&mut out, name);
                write_supersede_inputs(&mut out, inputs)?;
            }
            ArtifactCommand::AppendTransaction { mutations, transaction } => {
                crate::os_pack::write_varint_u64(&mut out, 19);
                write_command_str(&mut out, &transaction.id);
                write_command_str(&mut out, &transaction.tool);
                write_command_ops(&mut out, mutations)?;
            }
            ArtifactCommand::CommitTransaction { transaction_id } => {
                crate::os_pack::write_varint_u64(&mut out, 20);
                write_command_str(&mut out, transaction_id);
            }
            ArtifactCommand::AbortTransaction { transaction_id } => {
                crate::os_pack::write_varint_u64(&mut out, 21);
                write_command_str(&mut out, transaction_id);
            }
        }
        Ok(out)
    }

    /// 🛬️ Decodes one whole binary command, all-or-nothing: bytes past its end refuse it, and every operation decoded
    /// before a failure retires through its technology's cold disposal — a refusal never drops a live operation.
    pub fn decode_command<P>(bytes: &[u8]) -> Result<Self, CommandDecodeError>
    where
        Op: self::Mutation<P>,
    {
        let mut reader = crate::os_pack::ByteReader::new(bytes);
        let command = Self::read_command::<P>(&mut reader)?;
        if reader.remaining() != 0 {
            let detail = format!("{} bytes past the command's end", reader.remaining());
            retire_command::<P, Op>(command);
            return Err(CommandDecodeError::Layout(crate::os_spr::ProtocolError::Malformed { what: "command", offset: reader.position() as u64, detail }));
        }
        Ok(command)
    }

    /// 📖️ The command at `reader`; its operation lists come last, so nothing can fail after one was decoded.
    fn read_command<P>(reader: &mut crate::os_pack::ByteReader<'_>) -> Result<Self, CommandDecodeError>
    where
        Op: self::Mutation<P>,
    {
        let format = reader.read_u8()?;
        if format != COMMAND_BINARY_FORMAT {
            return Err(crate::os_spr::ProtocolError::Malformed { what: "command format", offset: 0, detail: format!("unsupported command format {format}") }.into());
        }
        let ordinal = reader.read_varint_u64()?;
        match ordinal {
            0 => {
                let presence = reader.read_u8()?;
                let description = if presence & 0b01 != 0 { Some(read_command_str(reader)?) } else { None };
                let transaction = read_command_transaction(reader, presence)?;
                let mutations = read_command_ops::<P, Op>(reader)?;
                Ok(ArtifactCommand::Apply { mutations, description, transaction })
            }
            1 => Ok(ArtifactCommand::Undo),
            2 => Ok(ArtifactCommand::Redo),
            3 => {
                let policy = undo_policy_from_ordinal(reader.read_u8()?)?;
                let presence = reader.read_u8()?;
                let semantic_command = if presence & 0b01 != 0 {
                    let len = reader.read_varint_u64()?;
                    let nested_bytes = reader.read_bytes(len as usize)?;
                    Some(Box::new(ArtifactCommand::<Op>::decode_command::<P>(nested_bytes)?))
                } else {
                    None
                };
                Ok(ArtifactCommand::UndoWithPolicy { policy, semantic_command })
            }
            4 => {
                let presence = reader.read_u8()?;
                let message = if presence & 0b01 != 0 { Some(read_command_str(reader)?) } else { None };
                let author_count = reader.read_varint_u64()?;
                let mut authors = Vec::with_capacity(author_count as usize);
                for _ in 0..author_count {
                    let id = read_command_str(reader)?;
                    let name = read_command_str(reader)?;
                    authors.push(Author { id, name, avatar: None });
                }
                Ok(ArtifactCommand::CommitCheckpoint { message, authors })
            }
            5 => Ok(ArtifactCommand::CreateAlternative { name: read_command_str(reader)? }),
            6 => Ok(ArtifactCommand::SwitchAlternative { alternative_id: read_command_str(reader)? }),
            7 => Ok(ArtifactCommand::CheckoutCheckpoint { checkpoint_id: read_command_str(reader)? }),
            9 => {
                let len = reader.read_varint_u64()?;
                let bytes = reader.read_bytes(len as usize)?;
                let mut pos = 0;
                let envelope = crate::os_spr::decode_envelope(bytes, &mut pos).map_err(|error| crate::os_spr::ProtocolError::Malformed { what: "ingest envelope", offset: 0, detail: error.to_string() })?;
                Ok(ArtifactCommand::IngestRemote { envelope })
            }
            10 => Ok(ArtifactCommand::PruneDrafts),
            11 => {
                let presence = reader.read_u8()?;
                let description = if presence & 0b01 != 0 { Some(read_command_str(reader)?) } else { None };
                let transaction = read_command_transaction(reader, presence)?;
                let lane = history_lane_from_ordinal(reader.read_u8()?)?;
                let mutations = read_command_ops::<P, Op>(reader)?;
                Ok(ArtifactCommand::ApplyInLane { mutations, description, lane, transaction })
            }
            13 => Ok(ArtifactCommand::UndoInLane { lane: history_lane_from_ordinal(reader.read_u8()?)? }),
            14 => Ok(ArtifactCommand::RedoInLane { lane: history_lane_from_ordinal(reader.read_u8()?)? }),
            15 => {
                let policy = crate::os_spr::MergePolicy::from_u8(reader.read_u8()?).ok_or_else(|| crate::os_spr::ProtocolError::Malformed { what: "merge policy ordinal", offset: 1, detail: "unknown merge policy ordinal".to_string() })?;
                Ok(ArtifactCommand::SetMergePolicy { policy })
            }
            16 => {
                let conflict_id = read_command_str(reader)?;
                let resolution = conflict_resolution_from_ordinal(reader.read_u8()?)?;
                Ok(ArtifactCommand::ResolveConflict { conflict_id, resolution })
            }
            17 => {
                let presence = reader.read_u8()?;
                let scope = if presence & 0b01 != 0 { Some(read_command_str(reader)?) } else { None };
                Ok(ArtifactCommand::Supersede { scope, inputs: read_supersede_inputs::<P, Op>(reader)? })
            }
            18 => {
                let name = read_command_str(reader)?;
                Ok(ArtifactCommand::CreateAlternativeWithSupersede { name, inputs: read_supersede_inputs::<P, Op>(reader)? })
            }
            19 => {
                let transaction = protocol::TransactionRef { id: read_command_str(reader)?, tool: read_command_str(reader)? };
                Ok(ArtifactCommand::AppendTransaction { mutations: read_command_ops::<P, Op>(reader)?, transaction })
            }
            20 => Ok(ArtifactCommand::CommitTransaction { transaction_id: read_command_str(reader)? }),
            21 => Ok(ArtifactCommand::AbortTransaction { transaction_id: read_command_str(reader)? }),
            other => Err(crate::os_spr::ProtocolError::Malformed { what: "command variant", offset: 1, detail: format!("unknown command ordinal {other}") }.into()),
        }
    }
}

