///     pub enum NoteMembers, NoteMembersOpen {
///         Text("s.note.text", "1", "*", "note.text/v1") => (TextSnapshot, TextMutation),
///         Sketch("s.note.sketch", "1", "*", "note.sketch/v1") => (SketchSnapshot, SketchMutation),
