/// 📌️ One member document's position at the moment a `SpaceCheckpoint` was recorded.
/// 🔮️ serde stays TEST-ONLY: feeds `SpaceHistoryMutation`'s own `cfg_attr(test)` oracle
/// derive transitively (`CommitSpaceCheckpoint` → `SpaceCheckpoint` → this type). Production never
/// serializes through serde, so this never reaches a shipped plugin component.
#[derive(Clone, Debug, PartialEq, Eq, semio_framework_value::ToValue, semio_framework_value::FromValue)]
#[cfg_attr(test, derive(Serialize, Deserialize))]
#[cfg_attr(test, serde(rename_all = "camelCase"))]
#[value(rename_all = "camelCase")]
pub struct SpaceMemberPin {
    pub document_id: String,
    pub checkpoint_id: String,
    /// 🌿️ Empty string when the member had no active alternative (its own trunk) at pin time.
    #[cfg_attr(test, serde(default))]
    #[value(default)]
    pub alternative_id: String,
}

/// 🗄️ A space-wide checkpoint: one pin per registered member, so checking it out (or an
/// alternative built on top of it) fans out deterministically to every member's own VCS.
#[derive(Clone, Debug, PartialEq, Eq, semio_framework_value::ToValue, semio_framework_value::FromValue)]
#[value(rename_all = "camelCase")]
pub struct SpaceCheckpoint {
    pub id: String,
    #[value(skip_serializing_if = "Option::is_none")]
    pub parent_id: Option<String>,
    pub message: String,
    pub authors: Vec<Author>,
    pub timestamp: HybridLogicalTimestamp,
    pub members: Vec<SpaceMemberPin>,
}

/// 🔮️ serde stays TEST-ONLY — see `SpaceMemberPin`'s docstring above.
#[derive(Clone, Debug, PartialEq, Eq, semio_framework_value::ToValue, semio_framework_value::FromValue)]
#[cfg_attr(test, derive(Serialize, Deserialize))]
#[cfg_attr(test, serde(rename_all = "camelCase"))]
#[value(rename_all = "camelCase")]
pub struct SpaceAlternative {
    pub id: String,
    pub name: String,
    pub checkpoint_ids: Vec<String>,
}

/// 🏷️ Schema id of the space-wide history meta-document — `"os.space.history"`, under the
/// `os.` schema lattice (a generic os-shell abstraction, not the `s.` product lattice), separate
/// from `space::S_SPACE_SCHEMA`/`space::S_COLLECTION_SCHEMA` (this crate sits below `space` in the
/// dependency graph, so it declares its own constant rather than depending on that crate's). The
/// `.spr` extension (`SpaceHistorySnapshot::EXTENSION`, `"space-history"`) is unchanged.
pub const S_SPACE_HISTORY_SCHEMA: &str = "os.space.history";

#[path = "📜️space-history/🧬️schema/📸️snapshot/🪶️sqlite/🦀️.rs"]
pub mod space_history_sqlite;

/// 🗄️ Snapshot of the `S_SPACE_HISTORY_SCHEMA` (`"os.space.history"`) meta-document: itself
/// an ordinary `ArtifactVcs` document kind (dogfooded — no bespoke transport), holding the
/// space-level checkpoint/alternative graph that `SpaceHost` composes on top of every registered
/// member's own history.
#[derive(Clone, Debug, Default, PartialEq, Eq, semio_framework_value::ToValue, semio_framework_value::FromValue)]
#[value(rename_all = "camelCase")]
pub struct SpaceHistorySnapshot {
    pub checkpoints: Vec<SpaceCheckpoint>,
    /// 🌿️ Held in ASCENDING `id` order, not in creation order. Two facts force it: a branch
    /// list is unordered in the product (nothing reads `alternatives[0]` as "the first branch"), and
    /// only a canonical order makes `RemoveSpaceAlternative`'s inverse an exact inverse — re-adding
    /// a removed alternative by appending put it back at the END, so undoing a removal changed the
    /// document (`space_history_op_round_trips`: "operation inverse did not restore pre-state"). The
    /// same canonical order is what lets two replicas that created branches concurrently converge.
    pub alternatives: Vec<SpaceAlternative>,
    #[value(skip_serializing_if = "Option::is_none")]
    pub active_alternative_id: Option<String>,
}

#[path = "🧬️schema/🧬️mutations/🦀️.rs"]
mod space_history_mutations;
pub use space_history_mutations::{CommitSpaceCheckpoint, CreateSpaceAlternative, RemoveSpaceAlternative, RemoveSpaceCheckpoint, RestoreActiveSpaceAlternative, SpaceHistoryMutation, SwitchSpaceAlternative};

#[derive(Clone, Debug, Default, PartialEq, semio_framework_value::ToValue, semio_framework_value::FromValue)]
#[value(rename_all = "camelCase")]
pub struct SpaceHistoryDiff {
    #[value(skip_serializing_if = "Option::is_none")]
    pub add_checkpoint: Option<SpaceCheckpoint>,
    #[value(skip_serializing_if = "Option::is_none")]
    pub remove_checkpoint_id: Option<String>,
    #[value(skip_serializing_if = "Option::is_none")]
    pub add_alternative: Option<SpaceAlternative>,
    #[value(skip_serializing_if = "Option::is_none")]
    pub remove_alternative_id: Option<String>,
    #[value(default, skip_serializing_if = "Option::is_none")]
    pub set_active_alternative_id: Option<Option<String>>,
}

impl MutationDiff<SpaceHistorySnapshot> for SpaceHistoryDiff {
    fn apply(&self, snapshot: &SpaceHistorySnapshot) -> crate::os_spr::MutationApplyResult<SpaceHistorySnapshot> {
        let mut next = snapshot.clone();
        if let Some(checkpoint) = &self.add_checkpoint {
            if next.checkpoints.iter().any(|existing| existing.id == checkpoint.id) {
                return Err(crate::os_spr::MutationApplyError::new("mutation.apply.duplicate-target", format!("checkpoint {} already exists", checkpoint.id)).at(["checkpoints", checkpoint.id.as_str()]));
            }
            next.checkpoints.push(checkpoint.clone());
        }
        if let Some(checkpoint_id) = &self.remove_checkpoint_id {
            if !next.checkpoints.iter().any(|checkpoint| checkpoint.id == *checkpoint_id) {
                return Err(crate::os_spr::MutationApplyError::new("mutation.apply.missing-target", format!("checkpoint {checkpoint_id} does not exist")).at(["checkpoints", checkpoint_id.as_str()]));
            }
            next.checkpoints.retain(|checkpoint| checkpoint.id != *checkpoint_id);
        }
        if let Some(alternative) = &self.add_alternative {
            if next.alternatives.iter().any(|existing| existing.id == alternative.id) {
                return Err(crate::os_spr::MutationApplyError::new("mutation.apply.duplicate-target", format!("alternative {} already exists", alternative.id)).at(["alternatives", alternative.id.as_str()]));
            }
            let position = next.alternatives.partition_point(|existing| existing.id < alternative.id);
            next.alternatives.insert(position, alternative.clone());
        }
        if let Some(alternative_id) = &self.remove_alternative_id {
            if !next.alternatives.iter().any(|alternative| alternative.id == *alternative_id) {
                return Err(crate::os_spr::MutationApplyError::new("mutation.apply.missing-target", format!("alternative {alternative_id} does not exist")).at(["alternatives", alternative_id.as_str()]));
            }
            next.alternatives.retain(|alternative| alternative.id != *alternative_id);
        }
        if let Some(active) = &self.set_active_alternative_id {
            if let Some(alternative_id) = active {
                if !next.alternatives.iter().any(|alternative| alternative.id == *alternative_id) {
                    return Err(crate::os_spr::MutationApplyError::new("mutation.apply.missing-target", format!("active alternative {alternative_id} does not exist")).at(["activeAlternativeId"]));
                }
            }
            next.active_alternative_id = active.clone();
        }
        Ok(next)
    }

    fn absorb(&mut self, other: Self) {
        if other.add_checkpoint.is_some() {
            self.add_checkpoint = other.add_checkpoint;
        }
        if other.remove_checkpoint_id.is_some() {
            self.remove_checkpoint_id = other.remove_checkpoint_id;
        }
        if other.add_alternative.is_some() {
            self.add_alternative = other.add_alternative;
        }
        if other.remove_alternative_id.is_some() {
            self.remove_alternative_id = other.remove_alternative_id;
        }
        if other.set_active_alternative_id.is_some() {
            self.set_active_alternative_id = other.set_active_alternative_id;
        }
    }
}

impl DiffRegions for SpaceHistoryDiff {
    fn touches(&self) -> TouchedPaths {
        let mut regions = Vec::new();
        if self.add_checkpoint.is_some() || self.remove_checkpoint_id.is_some() {
            regions.push("checkpoints");
        }
        if self.add_alternative.is_some() || self.remove_alternative_id.is_some() {
            regions.push("alternatives");
        }
        if self.set_active_alternative_id.is_some() {
            regions.push("activeAlternativeId");
        }
        TouchedPaths::new(regions)
    }
}

// 🎯️ B2: `ArtifactStore`'s shared impl block now requires `P: ArtifactPack` + `Mutation: OpText
// + OpBinary` for every instantiation (the pack+spr binary snapshot pipeline, needed by
// `SpaceHost::attach_backbone`'s real backbone-attach path — this dogfooded meta-document DOES
// cross a real wire once a backbone is attached, see `studio_vcs_host_meta_document_is_backbone_
// attachable_and_detachable`). `SpaceCheckpoint`/`SpaceAlternative` embed foreign types
// (`crate::os_vcs::Author`, `crate::os_spr::HybridLogicalTimestamp`) that cannot derive `crate::os_dsl::DslRecord`
// (orphan rule; `dsl`'s own dependency graph would cycle back through `protocol`), so a full
// `#[derive(DslArtifact)]`/`#[derive(DslOps)]` grammar is out of reach here without a larger
// dedicated field-mirroring effort (tracked as a B9 follow-up, same as the `serde_json::Value`-
// projected apps' analogous DSL-quality gap — see `impl ArtifactPack for serde_json::Value`
// above). BINARY face: real pack `Shape::Value` TLV bytes via `pack_rt::encode_json_value`
// (compliant structured binary per this wave's scope ruling — NOT raw JSON text bytes, unlike
// the deleted `serde_json::to_vec` hatch this replaces). TEXT face: JSON text, the same
// documented, scoped exception the `Value`-projected apps already have.
// 🎯️ `renormalize_whole_number_floats` moved into `pack_rt` (this file's :209) — general
// property of `pack_rt::decode_json_value`'s output, not specific to this type; `semio_compose_rs`'s
// `ComposeWireMutation` needs the exact same fix and calls the same `pack_rt::` function.
use pack_rt::renormalize_whole_number_floats;

impl OpText for SpaceHistoryMutation {
    fn print_op(&self) -> String {
        semio_framework_pack_json::to_json_string(self)
    }
    fn parse_op(line: &str) -> Result<Self, TextError> {
        semio_framework_pack_json::from_json_str(line, semio_framework_pack_json::JsonMemberPolicy::Reject).map_err(|error| TextError::new(error.kind, error.message, TextSpan::at(1, 1)))
    }
}
impl OpBinary for SpaceHistoryMutation {
    fn encode_op(&self) -> Result<Vec<u8>, crate::os_spr::ProtocolError> {
        let value = semio_framework_value::ToValue::to_value(self);
        Ok(pack_rt::encode_pack_value(&value))
    }
    fn decode_op(bytes: &[u8]) -> Result<Self, crate::os_spr::ProtocolError> {
        let value = pack_rt::decode_pack_value(bytes).map_err(|error| crate::os_spr::ProtocolError::Malformed { what: "space history op", offset: 0, detail: error.to_string() })?;
        semio_framework_value::FromValue::from_value(renormalize_whole_number_floats(value)).map_err(|error| crate::os_spr::ProtocolError::Malformed { what: "space history op", offset: 0, detail: error.to_string() })
    }
}
impl ArtifactDsl for SpaceHistorySnapshot {
    const EXTENSION: &'static str = "space-history";
    fn parse_dsl(text: &str) -> Result<Self, TextError> {
        semio_framework_pack_json::from_json_str(text, semio_framework_pack_json::JsonMemberPolicy::Reject).map_err(|error| TextError::new(error.kind, error.message, TextSpan::at(1, 1)))
    }
    fn print_dsl(&self) -> String {
        semio_framework_pack_json::to_json_string(self)
    }
}
impl ArtifactPack for SpaceHistorySnapshot {
    fn sqlite_snapshot_codec() -> Option<ArtifactSqliteSnapshotCodec> {
        Some(<Self as ArtifactSqliteSnapshot>::sqlite_codec())
    }
    fn encode_pack_with(&self, _options: &PackEncodeOptions) -> Result<Vec<u8>, PackError> {
        let value = semio_framework_value::ToValue::to_value(self);
        Ok(pack_rt::encode_pack_value(&value))
    }
    fn decode_pack_with(bytes: &[u8], _options: &PackDecodeOptions) -> Result<Self, PackError> {
        let value = pack_rt::decode_pack_value(bytes)?;
        semio_framework_value::FromValue::from_value(renormalize_whole_number_floats(value)).map_err(|error| PackError::Schema(error.to_string()))
    }
}
