    let mut wrong_owner = crate::os_vcs::ArtifactGroupVisibilityOwner::new();
    let wrong_view = wrong_owner.view();
    let next: ArtifactCursorOwners = serde_json::from_value(fixture["before"].clone()).expect("cancelled cursor owner");
